if (!m) { console.error('NO SCRIPT TAG FOUND'); process.exit(1); }
fs.writeFileSync('/tmp/ashfall_script.js', m[1]);
console.log('extracted', m[1].length, 'chars');
"
node --check /tmp/ashfall_script.js && echo "SYNTAX OK"

